// Go benchmarks for the tabnas engine via the json (strict) and jsonic
// (relaxed) grammars, against an encoding/json baseline.
//
// Fixtures are generated by ../genfixture.js into the directory named by
// BENCH_FIXTURE_DIR (run via ../run-bench.sh, which sets it). Run:
//
//	go test -bench=. -benchmem -run='^$' -benchtime=2s
package tabnasbench

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"

	tabnasjson "github.com/tabnas/json/go"
	jsonic "github.com/tabnas/jsonic/go"
)

func fixture(b *testing.B, name string) string {
	dir := os.Getenv("BENCH_FIXTURE_DIR")
	if dir == "" {
		b.Skip("BENCH_FIXTURE_DIR not set (run via ci/bench/run-bench.sh)")
	}
	data, err := os.ReadFile(filepath.Join(dir, name))
	if err != nil {
		b.Fatal(err)
	}
	return string(data)
}

func benchTabnasJson(b *testing.B, src string) {
	j := tabnasjson.Make()
	if _, err := j.Parse(src); err != nil {
		b.Fatal(err)
	}
	b.ReportAllocs()
	b.SetBytes(int64(len(src)))
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		if _, err := j.Parse(src); err != nil {
			b.Fatal(err)
		}
	}
}

func benchJsonic(b *testing.B, src string) {
	j := jsonic.Make(jsonic.Options{})
	if _, err := j.Parse(src); err != nil {
		b.Fatal(err)
	}
	b.ReportAllocs()
	b.SetBytes(int64(len(src)))
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		if _, err := j.Parse(src); err != nil {
			b.Fatal(err)
		}
	}
}

func BenchmarkJsonRecords1MB(b *testing.B) { benchTabnasJson(b, fixture(b, "records-1mb.json")) }
func BenchmarkJsonEscaped1MB(b *testing.B) {
	benchTabnasJson(b, fixture(b, "records-escaped-1mb.json"))
}
func BenchmarkJsonNumbers1MB(b *testing.B)  { benchTabnasJson(b, fixture(b, "numbers-1mb.json")) }
func BenchmarkJsonRecords16KB(b *testing.B) { benchTabnasJson(b, fixture(b, "records-16kb.json")) }
func BenchmarkJsonNested(b *testing.B)      { benchTabnasJson(b, fixture(b, "nested-256.json")) }

// The non-ASCII arm. Every other fixture here is ASCII — the escape-dense
// one included, since escape SEQUENCES are ASCII bytes — so without this
// the per-character fallback scan path is never measured on either side.
func BenchmarkJsonCJK1MB(b *testing.B) { benchTabnasJson(b, fixture(b, "records-cjk-1mb.json")) }

func BenchmarkJsonTiny(b *testing.B) { benchTabnasJson(b, `{"a":1,"b":[true,null,2.5],"c":"x"}`) }
func BenchmarkJsonPadded(b *testing.B) {
	benchJsonic(b, `{"a":1}`+strings.Repeat(" ", 10000))
}

// Pathology fixtures: one axis each, everything else small. The matrix
// above is all "ordinary document, made large", and an ordinary document
// is wide AND shallow AND small-tokened at once, so no single axis gets
// far enough to separate O(n) from O(n^2). Both quadratics found in this
// engine hid there.
func BenchmarkJsonWide40K(b *testing.B) { benchTabnasJson(b, fixture(b, "wide-40k.json")) }
func BenchmarkJsonLongString1MB(b *testing.B) {
	benchTabnasJson(b, fixture(b, "longstring-1mb.json"))
}
func BenchmarkJsonNumericEdge1MB(b *testing.B) {
	benchTabnasJson(b, fixture(b, "numeric-edge-1mb.json"))
}
func BenchmarkJsonSeparators1MB(b *testing.B) {
	benchTabnasJson(b, fixture(b, "separators-1mb.json"))
}

// Per-parse FIXED cost and nothing else: grammar install is amortised by
// the harness, so what is left is what every call pays however small the
// input. BenchmarkJsonPadded measures the skip loop instead.
func BenchmarkJsonSmallest(b *testing.B) { benchTabnasJson(b, fixture(b, "tiny.json")) }

// Ambiguity, the classic parser pathology, which strict JSON cannot
// express: every line here opens looking like an implicit map and only
// resolves at its end, so the alternate selector cannot settle early.
func BenchmarkJsonicAmbiguous1MB(b *testing.B) {
	benchJsonic(b, fixture(b, "ambiguous-1mb.jsonic"))
}

func BenchmarkJsonicRecords1MB(b *testing.B) { benchJsonic(b, fixture(b, "records-1mb.json")) }
func BenchmarkJsonicText1MB(b *testing.B)    { benchJsonic(b, fixture(b, "text-1mb.jsonic")) }

func BenchmarkStdlibRecords1MB(b *testing.B) {
	src := []byte(fixture(b, "records-1mb.json"))
	b.ReportAllocs()
	b.SetBytes(int64(len(src)))
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		var v any
		if err := json.Unmarshal(src, &v); err != nil {
			b.Fatal(err)
		}
	}
}
